//! # Patient domain model
//!
//! A patient is the central entity of the system. Every appointment, medical
//! record, and audit entry ultimately points back to a patient.

use chrono::{DateTime, NaiveDate, Utc};
use serde::{Deserialize, Serialize};
use uuid::Uuid;

/// A registered patient.
///
/// # Fields
///
/// - `id` — unique identifier, generated by the database on insert.
/// - `nin` — National Identification Number. Unique across all patients.
/// - `first_name`, `last_name` — patient's legal names.
/// - `date_of_birth` — stored as a date (no time component).
/// - `blood_type` — optional; may be unknown at registration time.
/// - `created_at`, `updated_at` — audit timestamps, set by the database.
/// - `deleted_at` — soft-delete marker. `None` means the patient is active.
#[derive(Debug, Clone, Serialize, Deserialize, sqlx::FromRow)]
pub struct Patient {
    pub id: Uuid,
    pub nin: String,
    pub first_name: String,
    pub last_name: String,
    pub date_of_birth: NaiveDate,
    pub blood_type: Option<BloodType>,
    pub created_at: DateTime<Utc>,
    pub updated_at: DateTime<Utc>,
    pub deleted_at: Option<DateTime<Utc>>,
}

/// The eight ABO/Rh blood types.
///
/// Stored in Postgres as `TEXT` with a `CHECK` constraint. This is
/// intentional: Postgres native `ENUM` types are painful to evolve
/// (adding a value requires `ALTER TYPE`, and removing one is impossible
/// without recreating the type). A `TEXT` column with a constraint gives
/// us the same safety with far easier migrations.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, sqlx::Type)]
#[sqlx(type_name = "TEXT")]
pub enum BloodType {
    #[serde(rename = "A+")]
    APositive,
    #[serde(rename = "A-")]
    ANegative,
    #[serde(rename = "B+")]
    BPositive,
    #[serde(rename = "B-")]
    BNegative,
    #[serde(rename = "AB+")]
    ABPositive,
    #[serde(rename = "AB-")]
    ABNegative,
    #[serde(rename = "O+")]
    OPositive,
    #[serde(rename = "O-")]
    ONegative,
}